<?php require 'auth.php'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $st=$pdoAuth->prepare('SELECT * FROM usuarios WHERE nombre=?');$st->execute([trim($_POST['nombre']??'')]);$u=$st->fetch(PDO::FETCH_ASSOC);if($u&&password_verify($_POST['contrasena']??'',$u['contrasena'])){$_SESSION['usuario']=$u['id_usuario'];header('Location: index.php');exit;} $error='Usuario o contraseña incorrectos.';} ?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acceso | Visitador Médico</title><link rel="stylesheet" href="css/styles.css"></head><body class="login-page"><form method="post" class="card login-card"><div class="brand-mark">VM</div><h1>Visitador Médico</h1><p class="text-muted">Ingresa a tu espacio de trabajo</p><?php if($error): ?><div class="alert-error"><?=htmlspecialchars($error)?></div><?php endif; ?><label>Usuario<input name="nombre" required autocomplete="username"></label><label>Contraseña<input type="password" name="contrasena" required autocomplete="current-password"></label><button class="btn btn-primary" type="submit">Iniciar sesión</button><small class="text-muted">Demo inicial: Demo / Heather323</small></form></body></html>